<section class="hx-page-heading"><p class="hx-eyebrow">DIGITAL DELIVERY</p><h1>My Key</h1><p class="hx-muted">Delivered product keys for this signed-in account. Keep them private and save a secure copy.</p></section><section id="keysList" class="hx-list"><div class="hx-loading">Loading key history…</div></section>
<script>(()=>{const box=document.getElementById('keysList'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));fetch('/api/store/orders',{credentials:'same-origin'}).then(async r=>{const d=await r.json();if(r.status===401){location.href='/login?next='+encodeURIComponent(location.pathname+location.search);return}if(!r.ok)throw Error(d.error||'Could not load key history.');const rows=(d.orders||[]).filter(o=>o.delivery_key);box.innerHTML=rows.length?rows.map(o=>`<article class="hx-panel hx-key-card"><div><b>${esc(o.product_name||'Product')} · ${esc(o.duration||'')}</b><div class="hx-muted">${new Date(Number(o.created_at)*1000).toLocaleString()} · ${esc(o.order_id||'')}</div></div><code>${esc(o.delivery_key)}</code><button class="hx-button hx-secondary" type="button" data-copy="${esc(o.delivery_key)}">Copy key</button></article>`).join(''):'<section class="hx-panel">No delivered keys yet. New keys appear here after an order completes.</section>';box.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);b.textContent='Copied'}catch{b.textContent='Select and copy the key above'}})}).catch(e=>box.textContent=e.message)})();</script>
